<?php
/** Reports, live moderation, copyright/takedown and appeal history. */
defined( 'ABSPATH' ) || exit;
final class VWLB_Moderation {
	public static function report($data){if(!is_user_logged_in())return VWLB_Helpers::error('vwlb_login_required',__('Sign in to report content.',VWLB_TEXT_DOMAIN),401);$rate=VWLB_Security::rate_limit('media_report',10,HOUR_IN_SECONDS);if(is_wp_error($rate))return $rate;$target_type=VWLB_Helpers::enum($data['target_type']??'',array('video','live','caption','chat'),'');$target_id=absint($data['target_id']??0);$reason=VWLB_Helpers::text($data['reason']??'',191);if(!$target_type||!$target_id||!$reason)return VWLB_Helpers::error('vwlb_report_invalid',__('Target and reason are required.',VWLB_TEXT_DOMAIN));global $wpdb;$now=VWLB_Helpers::now();$wpdb->insert(VWLB_Helpers::table('moderation'),array('public_id'=>VWLB_Helpers::public_id('mod'),'target_type'=>$target_type,'target_id'=>$target_id,'reason'=>$reason,'action'=>'reported','status'=>'open','severity'=>VWLB_Helpers::enum($data['severity']??'medium',array('low','medium','high','critical'),'medium'),'note'=>VWLB_Helpers::textarea($data['note']??'',10000),'evidence_json'=>VWLB_Helpers::json_encode($data['evidence']??array()),'reporter_id'=>get_current_user_id(),'created_at'=>$now,'updated_at'=>$now));$id=(int)$wpdb->insert_id;VWLB_Helpers::audit('moderation',$id,'report','','open',$reason);do_action('vwlb_moderation_reported',$id,$data);return array('id'=>$id,'status'=>'open');}
	public static function decide($report_id,$action,$note){$report=VWLB_Repository::find('moderation',$report_id);if(!$report)return VWLB_Helpers::error('vwlb_report_missing',__('Report not found.',VWLB_TEXT_DOMAIN),404);if(!VWLB_Security::can(VWLB_Contracts::CAP_MODERATE,null,'moderation_decision'))return VWLB_Helpers::error('vwlb_forbidden',__('You cannot moderate media.',VWLB_TEXT_DOMAIN),403);$action=VWLB_Helpers::enum($action,array('dismiss','restrict','remove','block','slow_mode','restore','escalate'),'');if(!$action||!trim($note))return VWLB_Helpers::error('vwlb_moderation_note_required',__('A decision and reason are required.',VWLB_TEXT_DOMAIN),422);global $wpdb;$status=in_array($action,array('dismiss','restrict','remove','block','restore'),true)?'closed':'escalated';$wpdb->update(VWLB_Helpers::table('moderation'),array('action'=>$action,'status'=>$status,'note'=>VWLB_Helpers::textarea($note,10000),'reviewer_id'=>get_current_user_id(),'updated_at'=>VWLB_Helpers::now(),'closed_at'=>'closed'===$status?VWLB_Helpers::now():null),array('id'=>$report['id']));if('live'===$report['target_type']&&'slow_mode'===$action){$live=VWLB_Repository::find('live_events',$report['target_id']);if($live)VWLB_Repository::update_versioned('live_events',$live['id'],$live['version'],array('slow_mode_seconds'=>(int)apply_filters('vwlb_moderation_slow_mode_seconds',30,$report)));}if(in_array($report['target_type'],array('chat','live'),true)&&in_array($action,array('block','slow_mode'),true))do_action('vwlb_live_chat_moderation',$action,$report);if(in_array($report['target_type'],array('video','live'),true)&&in_array($action,array('restrict','remove','restore'),true)){$entity='video'===$report['target_type']?'videos':'live_events';$row=VWLB_Repository::find($entity,$report['target_id']);if($row){$new='restore'===$action?('video'===$report['target_type']?'published':'scheduled'):('remove'===$action?'removed':'restricted');VWLB_Repository::update_versioned($entity,$row['id'],$row['version'],array('status'=>$new));VWLB_Helpers::outbox(ucfirst($report['target_type']).ucfirst($new),$report['target_type'],$row['id'],array('reason_category'=>$report['reason']));}}VWLB_Helpers::audit('moderation',$report['id'],'decide',$report['status'],$status,$note,array('action'=>$action));return array('id'=>$report['id'],'status'=>$status,'action'=>$action);}
	public static function file_takedown($data){$rate=VWLB_Security::rate_limit('takedown',5,DAY_IN_SECONDS);if(is_wp_error($rate))return $rate;$target_type=VWLB_Helpers::enum($data['target_type']??'',array('video','live'),'');$target_id=absint($data['target_id']??0);$basis=VWLB_Helpers::text($data['rights_basis']??'',191);if(!$target_type||!$target_id||!$basis)return VWLB_Helpers::error('vwlb_takedown_invalid',__('Target and rights basis are required.',VWLB_TEXT_DOMAIN));global $wpdb;$now=VWLB_Helpers::now();$wpdb->insert(VWLB_Helpers::table('takedowns'),array('public_id'=>VWLB_Helpers::public_id('td'),'target_type'=>$target_type,'target_id'=>$target_id,'claimant_id'=>get_current_user_id(),'claimant_contact_hash'=>hash_hmac('sha256',sanitize_email($data['contact']??''),wp_salt('auth')),'rights_basis'=>$basis,'evidence_json'=>VWLB_Helpers::json_encode($data['evidence']??array()),'status'=>'reported','created_at'=>$now,'updated_at'=>$now));$id=(int)$wpdb->insert_id;VWLB_Helpers::audit('takedown',$id,'file','','reported',$basis);do_action('vwlb_takedown_filed',$id,$data);return array('id'=>$id,'status'=>'reported');}
	public static function transition_takedown($id,$to,$expected_version,$reason){$case=VWLB_Repository::find('takedowns',$id);if(!$case)return VWLB_Helpers::error('vwlb_takedown_missing',__('Takedown case not found.',VWLB_TEXT_DOMAIN),404);$owner=(int)$case['claimant_id']===get_current_user_id();if(!$owner&&!VWLB_Security::can(VWLB_Contracts::CAP_MODERATE,null,'takedown_decision'))return VWLB_Helpers::error('vwlb_forbidden',__('You cannot update this case.',VWLB_TEXT_DOMAIN),403);$to=VWLB_Helpers::enum($to,VWLB_Contracts::TAKEDOWN_STATES,'');$assert=VWLB_State_Machine::assert('takedown',$case['status'],$to);if(is_wp_error($assert))return $assert;if(!$reason)return VWLB_Helpers::error('vwlb_reason_required',__('A reason is required.',VWLB_TEXT_DOMAIN),422);$updated=VWLB_Repository::update_versioned('takedowns',$case['id'],$expected_version,array('status'=>$to,'decision_reason'=>VWLB_Helpers::textarea($reason,10000),'reviewer_id'=>VWLB_Security::can(VWLB_Contracts::CAP_MODERATE)?get_current_user_id():0,'closed_at'=>in_array($to,array('removed','restored','closed'),true)?VWLB_Helpers::now():null));if(is_wp_error($updated))return $updated;if(in_array($to,array('restricted','removed','restored'),true)){$entity='video'===$case['target_type']?'videos':'live_events';$target=VWLB_Repository::find($entity,$case['target_id']);if($target){$status='restored'===$to?('videos'===$entity?'published':'scheduled'):('removed'===$to?'removed':'restricted');VWLB_Repository::update_versioned($entity,$target['id'],$target['version'],array('status'=>$status));VWLB_Helpers::outbox('Copyright'.ucfirst($to),$case['target_type'],$target['id'],array('case_public_id'=>$case['public_id']));}}VWLB_Helpers::audit('takedown',$case['id'],'transition',$case['status'],$to,$reason);return $updated;}
}
